// TH15 v1.00b st02.ecl.txt MainSub04 (1028-1054): midboss reward wave, 5 rounds x 4 GirlC02.
// Card frame 0 is the MainSub04 entry; source local time t maps to card frame 120 + t.
// Chapter entry, -9905 spawn gate and the enmCreateF boss gate are removed as approved.

const TIME_LIMIT: int = 2924;
const OPENING_BUFFER: int = 120;

// Source etSprite(0, 8, 6) -> TH15 type 8 rice, color 6 (bullet-types.md).
const TH15_RICE: int = 480;

// GirlC02_at etEx type 4 ACCEL: a=230, r=0.01, s=-999999 keeps the bullet angle taken at
// effect entry. Nothing turns the bullet before this, so that angle is the fire angle and is
// passed in as a value parameter.
xformdef ACCEL_230(dir: angle) {
    @230 set_gravity(0.01fx * cos(dir), 0.01fx * sin(dir));
    set_gravity(0fx, 0fx);
}

// GirlC02_at (441-480), reached through the synchronous call @GirlC02_at().
sub girl_fire() {
    wait(60);
    var rank: int = global(GVAR_RANK);
    // etCount(0, [-1], 1) stack value: !E 1, !N 24, !H 24, !LO 24.
    var ways: int = 24;
    if rank == RANK_EASY { ways = 1; }
    // diffI($C, 6, 6, 10, 16)
    var shots: int = 6;
    if rank == RANK_HARD { shots = 10; }
    if rank == RANK_LUNATIC { shots = 16; }
    // diffF(%A, 1.0, 1.0, 2.0, 2.0); %A += 0.3 after each shot, reset at every burst.
    var base_speed: fx = 1fx;
    if rank >= RANK_HARD { base_speed = 2fx; }
    for burst in 0..3 {                          // $B = 3
        var sp: fx = base_speed;
        var aim: angle = aim_player();           // etAngle(0, ANGLE_PLAYER, 0) once per burst
        for shot in 0..shots {
            for i in 0..ways {
                // etAim(0,3) fixed-direction ring: alpha + 2*pi*i/N with alpha = player angle.
                var a: angle = aim + (((i * 65536) / ways) as angle);
                // etEx type 2 ANIM a=1: birth displacement position -= 4*velocity.
                var back: fx = 4fx * sp;
                _ = fire(TH15_RICE, 6,
                         $self_x - back * cos(a),
                         $self_y - back * sin(a),
                         sp, a, ACCEL_230(a), none);
            }
            sp = sp + 0.3fx;
            wait(8);
        }
        wait(80);
    }
}

// GirlC02 (416-439). mirror=1 is enmCreateMF: the creation helper sets the child mirror,
// which reflects the horizontal part of moveVel/moveVelTime below.
async sub girl(mirror: int) {
    var a0: angle = 45deg;
    var a1: angle = 0deg;
    var a3: angle = -4096bam;                    // -22.5 deg
    if mirror != 0 {
        a0 = 135deg;                             // mirrored 45 deg
        a1 = 180deg;                             // mirrored 0 deg
        a3 = 36864bam;                           // mirrored -22.5 deg = 202.5 deg
    }
    set_invuln(65535);
    set_hurtbox(16fx);                           // setHurtbox(32,32): circle radius 32/2
    set_hitbox(12fx);                            // setHitbox(24,24): circle radius 24/2
    move_vel(0, a0, 3fx, EASE_LINEAR);           // moveVel(45deg, 3.0)
    move_vel(80, a1, 0.5fx, EASE_QUAD_IN);       // moveVelTime(80, 1, 0.0, 0.5)
    girl_fire();                                 // @GirlC02_at(): synchronous, blocks this task
    move_vel(0, -90deg, 0fx, EASE_LINEAR);       // moveVel(-90deg, 0.0)
    move_vel(70, a3, 4fx, EASE_QUAD_IN);         // moveVelTime(70, 1, -22.5deg, 4.0)
    wait(70);
    loop { wait(1000); }                         // source GirlC02_428 infinite wait loop
}

// One enmCreateF/enmCreateMF: RANDF2*16 offset on the base x, one random draw per spawn.
sub spawn_girl(base: fx, mirror: int) {
    var r: int = rand(65536);
    var u: fx = ((r - 32768) as fx) / 32768;
    _ = spawn_enemy(base + 16fx * u, -24fx, 600, 0, 1000, 0, girl(mirror));
}

// MainSub04 (1028-1054): wait(61), $A = 5, then four spawns 80 frames apart per round.
async sub pattern() {
    wait(OPENING_BUFFER);
    wait(61);
    for round in 0..5 {
        spawn_girl(-192fx, 0);
        wait(80);
        spawn_girl(192fx, 1);
        wait(80);
        spawn_girl(-256fx, 0);
        wait(80);
        spawn_girl(256fx, 1);
        wait(80);
    }
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
